TN.defSec("wounds",{"wound-evaluation-preparation":{"id":"wound-evaluation-preparation","variants":[{"id":"wound-simple","o":{"N":[{"t":"Document mechanism, time, location, contamination, tetanus immunization status and allergies (latex)"}],"T":[{"t":"Local or regional anesthesia before preparing and evaluating the wound; neurovascular examination of the involved and distal areas before anesthesia (two-point discrimination normal < 6 mm)"},{"t":"Irrigation: low-pressure, slow gentle wash for simple uncontaminated wounds in highly vascular areas such as the face and scalp (sterile normal saline; tap water is safe and effective; warmed fluid is more comfortable)"},{"t":"Skin disinfection with a povidone iodine- or chlorhexidine-containing agent around the wound (avoid contact with nonintact skin); clean nonsterile gloves are adequate"},{"t":"Hemostasis: direct pressure preferred"},{"t":"Tetanus prophylaxis as indicated"}]},"name":"Simple clean wound","level":"III","imp":"Traumatic wound (laceration)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با پارگی تمیز ۳ سانتی‌متری ساعد از لبه شیشه ۲ ساعت پیش؛ بدون ضعف یا بی‌حسی.","why":"زخم ساده تمیز: بی‌حسی، شستشو، هموستاز و بستن؛ پروفیلاکسی آنتی‌بیوتیکی لازم نیست."},{"id":"wound-contaminated","o":{"N":[{"t":"Document mechanism, time, location, contamination, tetanus status and allergies"}],"I":[{"t":"X-ray; CT, MRI or ultrasound for foreign bodies with density similar to soft tissue","if":"foreign body or bone injury suspected"}],"A":[{"t":"Prophylactic antibiotic before significant tissue manipulation, with a β-lactam (most non-bite infections are staphylococci or streptococci); oral may be as effective as IV with sufficient spectrum and rapid absorption","if":"selected higher-risk wounds and populations","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Prophylactic antibiotics (see puncture wounds and bites)","if":"human bites, mammalian bites to the hand, other high-risk bites"}],"T":[{"t":"Local or regional anesthesia before irrigation; neurovascular examination before anesthesia"},{"t":"High-pressure irrigation with an 18-gauge catheter, syringe and splash guard (wound soaking is not effective)"},{"t":"Remove foreign debris with forceps; inspect the full depth and course of the wound"},{"t":"Debridement: elliptical excision around the wound edges with a surgical blade removes devitalized tissue"},{"t":"Delayed primary closure after 4 days of open wound management","if":"high risk of infection at first encounter"},{"t":"Tetanus prophylaxis as indicated"}],"Co":[{"t":"Surgical specialist","if":"extensive nonviable tissue, may need grafting"}]},"name":"Contaminated or high-risk wound","level":"II","imp":"Contaminated traumatic wound","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۵ ساله با پارگی عمیق پای آلوده به خاک و مدفوع حیوان در مزرعه ۸ ساعت پیش.","why":"زخم آلوده: شستشوی پرفشار، دبریدمان، در نظر گرفتن آنتی‌بیوتیک و تأخیر در بستن."}],"ch":"9","name":"Traumatic wound: evaluation and preparation","name_fa":"ارزیابی و آماده‌سازی زخم تروماتیک","cc":["wound-bite"],"keywords":"laceration, wound irrigation, hemostasis, debridement, foreign body, prophylactic antibiotics, delayed primary closure, tourniquet, زخم","status":"draft","features":["ثبت مکانیسم، زمان، محل و درجه آلودگی؛ درد، تورم، پارستزی و از دست رفتن عملکرد؛ عوامل مؤثر بر ترمیم (سن، محل، دارو، بیماری مزمن، کلوئید)؛ آلرژی به لاتکس و وضعیت واکسن کزاز","احساس جسم خارجی در بالغین به‌احتمال زیاد یعنی جسم باقی‌مانده","نیروی برشی: لبه صاف و آلودگی کم؛ فشاری: لاسراسیون ستاره‌ای؛ کششی: فلپ با بافت غیرزنده و خطر عفونت","خطر عفونت: نواحی مرطوب (آگزیلا، پرینه، دست و پا) بیشتر؛ صورت و سر کمتر (عروق زیاد)؛ زخم دهان آلوده؛ گزش حیوان/انسان و آلودگی مدفوعی خطر زیاد","ترمیم اولیه تأخیری پس از ۴ روز برای زخم‌های پرخطر در اولین مراجعه توصیه می‌شود"],"ddx":[{"n":"Tendon, nerve, vascular or joint injury","cm":1,"note":"معاینه در موقعیت زمان آسیب"},{"n":"Retained foreign body or bone injury |","cm":1},{"n":"Bite wound |"},{"n":"Heavily contaminated wound |"}],"redflags":["زخم روی مفصل (نفوذ به فضای مفصل)، تاندون یا عصب","جسم خارجی یا آلودگی شدید، بافت غیرزنده گسترده"],"guide":"# مراحل آماده‌سازی\n- بی‌حسی موضعی/ناحیه‌ای برای ارزیابی بهتر؛ معاینه عصبی‌عروقی قبل از بی‌حسی (تفکیک دو نقطه طبیعی < 6 mm).\n- شستشو: کم‌فشار برای زخم تمیز در صورت و سر؛ پرفشار با کاتتر 18 برای زخم آلوده؛ آب لوله‌کشی ایمن و مؤثر است؛ خیساندن مؤثر نیست؛ افزودن پوویدون ید یا H2O2 فایده ندارد.\n- هموستاز: فشار مستقیم ترجیح دارد؛ تورنیکت حداکثر 20–30 دقیقه.\n- جسم خارجی: رادیوگرافی ساده برای جسم کدر؛ CT، MRI یا سونوگرافی برای هم‌چگال بافت نرم؛ برداشتن مو فقط با قیچی 1–2 mm بالای پوست.\n- دبریدمان و در بافت غیرزنده گسترده مشاوره جراحی.","pearls":["آنتی‌بیوتیک پروفیلاکسی در اغلب زخم‌ها شواهد ندارد؛ برای گزش انسان، گزش پستانداران به دست و زخم‌های پرخطر توصیه می‌شود."],"section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 9: Evaluating and Preparing Wounds, pp. 81–84"},"wound-closure-methods":{"id":"wound-closure-methods","variants":[{"id":"closure-sutures","o":{"T":[{"t":"Simple interrupted percutaneous sutures (easiest, most common): needle at 90 degrees, evert edges, square knots (number of knots equal to the gauge, e.g. four for 4-0), all knots on one side"},{"t":"Continuous running sutures at a 65 degree angle","if":"long linear high-tension wounds"},{"t":"Buried dermal sutures with absorbable material; minimize the number of buried sutures (adipose closure unnecessary)","if":"reduce tension and close dead space"},{"t":"Continuous subcuticular sutures","if":"excellent approximation, absorbable, no removal"},{"t":"Vertical mattress sutures (far-far / near-near)","if":"wound edge eversion, deep and epidermal layers"},{"t":"Horizontal mattress sutures; [skin flaps, stellate lacerations] horizontal half-buried mattress sutures","if":"poor circulation, delicate areas"},{"t":"Suture size: 6-0 and 5-0 for low-tension areas such as the face; 3-0 and 4-0 for scalp, extremities and higher tension"}]},"name":"Sutures","level":"III","imp":"Wound closure by sutures","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زخم خطی ۴ سانتی‌متری ران با کشش متوسط که نیاز به بستن با بخیه دارد.","why":"بخیه قوی و قابل‌اعتماد برای زخم‌های با کشش."},{"id":"closure-nonsuture","o":{"T":[{"t":"Staples (scalp and areas where cosmetics matter less; not the face): align the edges, stapler perpendicular and centered, gentle pressure to evert the edges"},{"t":"Adhesive tapes (low tension, fragile wounds such as skin tears): tincture of benzoin adjunct, tape perpendicular to the wound about 3 mm apart, reinforce with parallel strips"},{"t":"Cyanoacrylate tissue adhesive: thin coat over the wound extending 5 to 10 mm on either side, repeat once dry","fl":[{"k":"ci","v":"over joints or areas of high tension"}]},{"t":"Hair apposition (scalp): twist strands of hair together on each side, then twist the two bundles and apply a drop of tissue adhesive","fl":[{"k":"ci","v":"wounds > 10 cm, grossly contaminated, uncontrolled bleeding, gaping wounds with significant tension"}]}]},"name":"Staples, tape, tissue adhesive, hair apposition","level":"III","imp":"Wound closure without sutures","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"پارگی ۵ سانتی‌متری پوست سر در مردی ۳۰ ساله؛ یا پاره‌شدن سطحی پوست (skin tear) در زن سالمند.","why":"انتخاب روش بر اساس محل، کشش و ظرافت پوست."}],"ch":"10","name":"Wound closure methods (sutures, staples, tape, adhesive)","name_fa":"روش‌های بستن زخم","cc":["wound-bite"],"keywords":"suture, staples, tissue adhesive, cyanoacrylate, steri-strips, hair apposition, absorbable, mattress, buried suture, subcuticular","status":"draft","features":["روش‌ها: ترمیم اولیه (بلافاصله)، ثانویه (ترمیم خودبه‌خود؛ برای زخم آلوده یا عفونی) و تأخیری (پک و بستن بعداً پس از رد عفونت)","عوامل انتخاب: زمان از آسیب، کشش زخم (ایستا یا پویا)، خطر اسکار؛ نتیجه زیبایی بیشتر به تکنیک بستگی دارد","گزینه‌ها: بخیه، استیپلر، نوار چسب، چسب بافتی و آپوزیسیون مو"],"ddx":[{"n":"Infected or heavily contaminated wound","cm":1,"note":"بستن اولیه نشود"},{"n":"High-tension wound","note":"بخیه یا استیپلر"},{"n":"Low-tension fragile wound (skin tear)","note":"نوار چسب"}],"redflags":["زخم عفونی یا آلودگی شدید"],"guide":"# بخیه\n- قابل جذب (استحکام کمتر از 60 روز؛ بدون نیاز به کشیدن) برای بافت عمقی؛ غیرقابل جذب مونوفیلامان برای پوست.\n- گیج بالا (5-0، 6-0) نازک برای مناطق کم‌کشش مثل صورت؛ گیج کوچک‌تر (3-0، 4-0) برای پوست سر و اندام.\n- لبه‌های پوست را اورت کن و فشار له‌کننده نده.\n# غیر بخیه\n- استیپلر: سریع، برای پوست سر؛ نه صورت.\n- نوار چسب: فقط کم‌کشش و شکننده (skin tear)؛ در رطوبت جدا می‌شود؛ با بنزوئین و نوارها عمود بر زخم با فاصله 3 mm.\n- چسب بافتی: قدرت معادل بخیه ساب‌کوتیکولار 4-0؛ نه روی مفصل یا کشش زیاد؛ 5–10 روز می‌افتد.\n- آپوزیسیون مو: زخم پوست سر تا 10 cm، بدون آلودگی شدید یا خونریزی.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 10: Methods for Wound Closure, pp. 85–95"},"scalp-forehead-laceration":{"id":"scalp-forehead-laceration","variants":[{"id":"scalp-lac-main","o":{"I":[{"t":"CT scan","if":"underlying skull fracture suspected"}],"T":[{"t":"Wound cleansing and irrigation; hemostasis with direct pressure or vessel clamping; palpate the base of the wound for skull fracture; debride devitalized edges"},{"t":"Close with surgical staples or simple interrupted sutures (nonabsorbable monofilament or rapidly absorbable)"},{"t":"Pressure dressing for the first 24 hours to reduce hematoma formation","if":"deep lacerations"},{"t":"Remove scalp staples or sutures in 10 to 14 days"}]},"name":"Scalp laceration","level":"III","imp":"Scalp laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۵ ساله با پارگی ۴ سانتی‌متری پوست سر بعد از افتادن؛ هوشیار و بدون علامت عصبی.","why":"پس از شستشو، هموستاز و لمس کف زخم، با استیپل یا بخیه بسته می‌شود."},{"id":"forehead-lac-main","o":{"I":[{"t":"CT scan","if":"underlying fracture suspected"}],"T":[{"t":"Superficial: 6-0 nonabsorbable interrupted suture, rapidly absorbable suture, or tissue adhesive"},{"t":"Deep (frontalis injury): close the muscular layer with buried 5-0 absorbable suture, then the epidermal layer with 6-0 nonabsorbable suture, skin closure strips or tissue adhesive"},{"t":"Eyebrow: minimize skin debridement and leave suture tails long"},{"t":"Remove forehead nonabsorbable sutures in 5 to 7 days"}]},"name":"Forehead laceration (superficial or deep)","level":"III","imp":"Forehead laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۵ ساله با پارگی پیشانی بعد از ضربه به لبه میز؛ پارگی عمیق دیده می‌شود.","why":"پارگی عمیق نیاز به بستن لایه عضلانی دارد."}],"ch":"11","name":"Scalp and forehead laceration","name_fa":"پارگی پوست سر و پیشانی","cc":["head-injury","wound-bite"],"keywords":"scalp laceration, forehead laceration, frontalis, staples, pressure dressing, eyebrow, skull fracture","status":"draft","features":["پوست ضخیم و چربی کم؛ در صورت عدم عفونت آشکار ترمیم اولیه حتی با تأخیر و حتی بعد از گزش","بعد از شستشو و هموستاز کف زخم را برای شکستگی جمجمه لمس کن؛ در شک به شکستگی CT","پیشانی سطحی بدون آسیب عضله frontalis؛ عمیق با آسیب frontalis","ابروها نشانه‌های مهم هم‌راستاسازی هستند؛ دبریدمان پوست را کم کن و دم بخیه را بلند بگذار"],"ddx":[{"n":"Underlying skull fracture |","cm":1},{"n":"Devitalized wound edges |"},{"n":"Deep forehead laceration (frontalis injury) |"}],"redflags":["شکستگی جمجمه قابل لمس یا شک به آن"],"guide":"پوست سر: استیپلر یا بخیه ساده منقطع مونوفیلامان غیرقابل‌جذب یا سریع‌الجذب؛ پانسمان فشاری 24 ساعت اول برای زخم‌های عمیق. بخیه/استیپل پوست سر 10–14 روز و بخیه پیشانی 5–7 روز بعد کشیده شود.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 11: Lacerations to The Face and Scalp, pp. 96–100"},"eyelid-laceration":{"id":"eyelid-laceration","variants":[{"id":"eyelid-lac-main","o":{"T":[{"t":"Close uncomplicated lacerations with nonabsorbable 6-0 or 7-0 simple interrupted percutaneous sutures","fl":[{"k":"ci","v":"tissue adhesive near the eye"}]},{"t":"Remove nonabsorbable sutures in 3 to 5 days"}],"Co":[{"t":"Ophthalmology","if":"ptosis, or complex wounds: inner surface of the lid, lid margin, lacrimal duct, tarsal plate"}]},"name":"Eyelid laceration","level":"II","imp":"Eyelid laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۰ ساله با پارگی ۱ سانتی‌متری پلک فوقانی بعد از ضربه؛ بینایی طبیعی.","why":"پارگی ساده پلک را می‌توان با بخیه ریز بست؛ موارد پیچیده به چشم‌پزشک ارجاع شود."}],"ch":"11","name":"Eyelid laceration","name_fa":"پارگی پلک","cc":["eye","head-injury"],"keywords":"eyelid laceration, canalicular laceration, lacrimal, tarsal plate, ptosis, medial canthus","status":"draft","features":["پلک نازک است و محافظت محدودی از گلوب و ساختارهای اطراف دارد","بررسی درگیری کانتوس، سیستم اشکی، نفوذ از طریق tarsal plate یا لبه پلک","آسیب در 6 تا 8 mm از کانتوس داخلی: خطر پارگی کانالیکول (به‌ویژه با شکستگی blow-out دیواره داخلی)"],"ddx":[{"n":"Globe injury |","cm":1},{"n":"Canalicular / lacrimal duct laceration |","cm":1},{"n":"Medial wall blow-out fracture |"},{"n":"Tarsal plate / lid margin involvement |"}],"redflags":["پتوز، پارگی لبه پلک، مجرای اشکی یا tarsal plate، سطح داخلی پلک"],"guide":"پارگی ساده پلک: بخیه منقطع پوستی غیرقابل‌جذب 6-0 یا 7-0؛ چسب بافتی نزدیک چشم نه؛ بخیه 3–5 روز بعد کشیده شود. ptosis یا پارگی پیچیده: چشم‌پزشک.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 11: Lacerations to The Face and Scalp, pp. 96–100"},"nose-ear-lip-laceration":{"id":"nose-ear-lip-laceration","variants":[{"id":"nose-lac","o":{"A":[{"t":"Course of oral antibiotics","if":"septal hematoma with nasal packing in place","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"Topical lidocaine into the nasal cavity or injected intradermal lidocaine with or without epinephrine"},{"t":"Superficial: 6-0 nonabsorbable monofilament simple interrupted sutures"},{"t":"Through all layers: begin with 5-0 nonabsorbable monofilament aligning the skin around the nasal canal entrances; close mucosa with 5-0 rapidly absorbable interrupted sutures; irrigate gently; avoid sutures directly in cartilage; finish with 6-0 nonabsorbable monofilament; remove percutaneous sutures in 3 to 5 days"},{"t":"Small unilateral septal hematoma: drain with an 18G needle; larger: incise; then anterior nasal packing"}]},"name":"Nasal laceration and septal hematoma","level":"III","imp":"Nasal laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با پارگی بینی بعد از مشت؛ ورم و احتقان یک‌طرفه بینی (هماتوم سپتوم).","why":"ترمیم لایه‌ای و تخلیه هماتوم سپتوم با پک برای جلوگیری از تجمع مجدد."},{"id":"ear-lac","o":{"T":[{"t":"Close superficial lacerations with 6-0 nonabsorbable monofilament interrupted sutures, cover exposed cartilage, minimize skin debridement"},{"t":"Nonadherent gauze over the laceration with a pressure dressing (gauze squares behind the ear, circumferential head wrap); discontinue after 24 hours if no hematoma"},{"t":"Remove nonabsorbable sutures in 5 to 7 days"}],"Co":[{"t":"Otolaryngology or plastic surgery","if":"complex lacerations, ear avulsions, auricular hematomas"}]},"name":"Ear laceration","level":"III","imp":"Ear laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۵ ساله با پارگی لاله گوش بعد از گیرکردن گوشواره.","why":"پوست را بدوزید و با پانسمان فشاری از هماتوم perichondral جلوگیری کنید."},{"id":"lip-lac","o":{"A":[{"t":"Oral antibiotics","if":"contaminated wounds or through-and-through lacerations","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"Isolated intraoral lip wounds < 1 cm often do not need sutures; large or gaping: rapidly absorbable 5-0 suture"},{"t":"Through-and-through not including the vermilion: close in layers: mucosa with 5-0 rapidly absorbable, irrigate from outside, orbicularis oris with 4-0 or 5-0 absorbable, skin with 6-0 nonabsorbable monofilament simple interrupted"},{"t":"Complicated: first stitch with 6-0 nonabsorbable monofilament at the vermilion–skin junction, then repair the vermilion and skin with the same suture; 5-0 rapidly absorbable for the mucosa"},{"t":"Remove nonabsorbable percutaneous sutures in 5 to 7 days"}]},"name":"Lip laceration","level":"III","imp":"Lip laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودکی ۸ ساله با پارگی ۱٫۵ سانتی‌متری لب پایین که مرز vermilion را درگیر می‌کند.","why":"اولین بخیه باید مرز vermilion را دقیق هم‌راستا کند."}],"ch":"11","name":"Nasal, ear and lip lacerations (including septal and auricular hematoma)","name_fa":"پارگی بینی، گوش و لب","cc":["head-injury","wound-bite","ent"],"keywords":"nasal laceration, septal hematoma, ear laceration, auricular hematoma, perichondral hematoma, lip laceration, vermilion border, orbicularis oris","status":"draft","features":["بینی: عمق و درگیری لایه‌ها را بررسی کن؛ غضروف مکشوف یا درگیری عمیق خطر عفونت را بالا می‌برد","هماتوم کوچک یک‌طرفه سپتوم را با سوزن 18G تخلیه کن یا اگر بزرگ است برش بزن؛ سپس پک قدامی و در نظر گرفتن آنتی‌بیوتیک خوراکی","گوش: پارگی‌های through-and-through اغلب با نزدیک کردن پوست بسته می‌شوند؛ پانسمان فشاری برای پیشگیری از هماتوم perichondral","لب: سه ناحیه پوست، مرز vermilion و مخاط؛ زخم داخل‌دهانی < 1 cm معمولاً بخیه نمی‌خواهد؛ شروع ترمیم پیچیده از اتصال vermilion–پوست"],"ddx":[{"n":"Septal hematoma |","cm":1},{"n":"Perichondral (auricular) hematoma |","cm":1},{"n":"Exposed cartilage |"},{"n":"Through-and-through lip laceration |"}],"redflags":["هماتوم سپتوم یا گوش","آواسیون گوش یا پارگی پیچیده"],"guide":"بینی سطحی: 6-0 مونوفیلامان غیرقابل‌جذب؛ همه لایه‌ها: شروع با 5-0 برای هم‌راستایی ورودی نازال، مخاط با 5-0 سریع‌الجذب، بدون بخیه مستقیم در غضروف، بخیه‌ها 3–5 روز. گوش: 6-0 غیرقابل‌جذب، فشار 24 ساعت؛ بخیه 5–7 روز. لب: لایه‌ای؛ آنتی‌بیوتیک خوراکی برای آلوده یا through-and-through.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 11: Lacerations to The Face and Scalp, pp. 96–100"},"cheek-facial-laceration":{"id":"cheek-facial-laceration","variants":[{"id":"cheek-lac-main","o":{"T":[{"t":"Superficial: 6-0 nonabsorbable monofilament simple interrupted sutures; tissue adhesive for appropriate size and location"},{"t":"Full-thickness cheek: begin with the intraoral mucosa using absorbable sutures; after irrigating the external wound close subcutaneous and skin layers with 5-0 or 6-0 material"},{"t":"Remove nonabsorbable percutaneous sutures in 5 to 7 days"}],"Co":[{"t":"Specialty consultation for operative repair","if":"parotid gland, parotid duct or facial nerve damage"}]},"name":"Cheek or facial laceration","level":"III","imp":"Facial laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۸ ساله با پارگی ۳ سانتی‌متری گونه؛ حرکت عصب فاسیال طبیعی.","why":"پس از رد آسیب پاروتید و عصب فاسیال، ترمیم لایه‌ای."}],"ch":"11","name":"Cheek and facial laceration","name_fa":"پارگی گونه و صورت","cc":["head-injury","wound-bite"],"keywords":"parotid duct, facial nerve, cheek laceration, facial laceration","status":"draft","features":["عمق زخم و آسیب به غده و مجرای پاروتید و عصب فاسیال را بررسی کن","مسیر مجرای پاروتید حدود 1.5 cm از نقطه میانی خط بین لبه تحتانی تراگوس تا گوشه دهان","پنج شاخه عصب فاسیال: temporal، zygomatic، buccal، marginal mandibular، cervical"],"ddx":[{"n":"Parotid gland / duct injury |","cm":1},{"n":"Facial nerve injury |","cm":1},{"n":"Full-thickness cheek laceration |"}],"redflags":["آسیب پاروتید، مجرای پاروتید یا عصب فاسیال"],"guide":"پارگی سطحی بدون عارضه: 6-0 مونوفیلامان غیرقابل‌جذب منقطع یا چسب بافتی؛ پارگی تمام‌ضخامت گونه: لایه‌ای، از مخاط داخل دهان با بخیه قابل‌جذب. بخیه 5–7 روز.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 11: Lacerations to The Face and Scalp, pp. 96–100"},"hand-forearm-laceration":{"id":"hand-forearm-laceration","variants":[{"id":"hand-lac-simple","o":{"I":[{"t":"AP and lateral X-ray","if":"bony injury, retained radiopaque foreign body or joint involvement suspected"}],"T":[{"t":"Control bleeding (manual BP cuff as temporary tourniquet for proximal injuries, or Penrose drain for distal finger injuries, for a limited time); examine tendons and nerves distal to the wound"},{"t":"Clean and irrigate all wounds after appropriate local anesthesia"},{"t":"Dorsal: most lacerations with 5-0 nonabsorbable sutures; consider subcuticular 5-0 absorbable sutures on the dorsum of the hand"},{"t":"Volar forearm and wrist: 4-0 or 5-0 nonabsorbable monofilament sutures; multiple parallel lacerations: horizontal mattress sutures crossing adjacent lacerations"},{"t":"Palm (no deep injury): close with sutures to re-oppose the skin creases; interrupted horizontal mattress sutures with 5-0 monofilament; median or ulnar nerve block may help exploration"},{"t":"Tetanus prophylaxis as indicated"},{"t":"Antibiotics ; prophylactic antibiotics are not routinely needed for uncomplicated hand lacerations","if":"complex wounds: bites, injuries more than 12 hours old, contaminated, exposed bone, significant comorbidities","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Hand specialist","if":"complex or extensive injuries, skin grafting, technically demanding repair, or injuries impacting function"}]},"name":"Uncomplicated dorsal or volar forearm, wrist, hand laceration","level":"III","imp":"Forearm / wrist / hand laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با پارگی ۳ سانتی‌متری پشت دست از شیشه؛ حرکت انگشتان و حس طبیعی.","why":"پس از رد آسیب تاندون و عصب، شستشو و بستن؛ آنتی‌بیوتیک روتین لازم نیست."}],"ch":"12","name":"Forearm, wrist and hand lacerations (dorsal, volar, palm)","name_fa":"پارگی ساعد، مچ و دست","cc":["wound-bite","limb-injury"],"keywords":"hand laceration, wrist laceration, palm laceration, volar laceration, self-inflicted, nerve injury, tendon exam, median nerve block, tourniquet","status":"draft","features":["شرح حال: شغل، زمان و مکانیسم و دست غالب؛ معاینه در حالت استراحت، حرکت فعال و مقاومت در برابر حرکت منفعل، عملکرد حرکتی و حسی اعصاب و تاندون‌ها و پرفیوژن","معاینه زخم در موقعیت زمان آسیب برای جلوگیری از جاماندن آسیب ساختارهای عمقی","پشت ساعد و دست: پوست نازک و نزدیک‌کردن لبه‌ها دشوار؛ شکل ولار: لاسراسیون خطی مچ و ساعد احتمال آسیب خودآزاری را مطرح می‌کند","کف دست: آسیب ساختارهای عمقی حتی با ظاهر خوش‌خیم"],"ddx":[{"n":"Artery, nerve, tendon or bone injury |","cm":1},{"n":"Self-inflicted injury (volar linear lacerations) |","cm":1},{"n":"Retained foreign body |"},{"n":"Joint capsule injury |"}],"redflags":["ضعف حرکتی، اختلال حسی یا نقص پرفیوژن دیستال","آسیب خودآزاری"],"guide":"آزمون عصب‌ها: رادیال (دورسی‌فلکشن مچ، حس فضای وب اول پشتی)، مدیان (ابداکشن شست از کف، حس نوک ولار اشاره)، اولنار (ابداکشن/اداکشن انگشتان، حس نوک ولار انگشت کوچک). شستشو و تمیز کردن با بی‌حسی؛ پروفیلاکسی کزاز؛ آنتی‌بیوتیک روتین برای لاسراسیون بدون عارضه لازم نیست.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 12: Injuries to the Arm, Hand, Fingertip, and Nail, pp. 101–107"},"clenched-fist-injury":{"id":"clenched-fist-injury","variants":[{"id":"fist-outpatient","o":{"I":[{"t":"X-ray of the hand (bony injury, foreign body, joint involvement)"}],"A":[{"t":"Amoxicillin-clavulanic acid, 3- to 5-day prophylactic course","fl":[{"k":"note","v":"dose not given in the book"}]}],"T":[{"t":"Wound usually not sutured; heals by secondary intention"},{"t":"Splint the hand in a position of function; close follow-up in 24 to 48 hours with strict return instructions for erythema, drainage or increased pain"},{"t":"Tetanus prophylaxis as indicated"}]},"name":"Fight bite without infection (outpatient)","level":"II","imp":"Clenched fist injury (fight bite)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۲ ساله با پارگی کوچک روی MCP سوم بعد از دعوا؛ بدون قرمزی یا درد شدید.","why":"زخم باز می‌ماند (healing secondary)، اسپلینت و آنتی‌بیوتیک پروفیلاکسی کوتاه."},{"id":"fist-infected","o":{"I":[{"t":"X-ray of the hand"}],"A":[{"t":"Ampicillin-sulbactam IV (or Cefoxitin IV)","fl":[{"k":"note","v":"dose not given in the book"}]}],"T":[{"t":"Splint in a position of function"},{"t":"Tetanus prophylaxis as indicated"}],"Co":[{"t":"Hand specialist (admission for IV antibiotics)"}]},"name":"Fight bite with signs of infection","level":"I","imp":"Infected clenched fist injury","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۴۰ ساله دو روز بعد از دعوا با تورم و قرمزی دست و تب خفیف.","why":"علائم عفونت: بستری و آنتی‌بیوتیک وریدی."}],"ch":"12","name":"Clenched fist injury (\"fight bite\")","name_fa":"آسیب مشت گره‌کرده (گزش مشت)","cc":["wound-bite","limb-injury"],"keywords":"fight bite, clenched fist, MCP laceration, Eikenella, ampicillin sulbactam, amoxicillin clavulanate","status":"draft","features":["لاسراسیون روی مفصل MCP پشتی بعد از برخورد مشت با دندان‌های جلو","عفونت پلی‌میکروبی شایع: S. aureus، Streptococcus، Corynebacterium، Eikenella corrodens","اغلب بخیه نمی‌شود و به‌صورت ثانویه بهبود می‌یابد"],"ddx":[{"n":"Joint capsule / tendon / bone injury |","cm":1},{"n":"Established infection |","cm":1},{"n":"Foreign body (tooth fragment) |"}],"redflags":["نشانه‌های عفونت (قرمزی، ترشح، درد افزایش‌یابنده)"],"guide":"اگر علائم عفونت موجود است بستری و آنتی‌بیوتیک وریدی؛ در درمان سرپایی اسپلینت در وضعیت عملکردی با 3 تا 5 روز آنتی‌بیوتیک پروفیلاکسی و پیگیری 24–48 ساعت.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 12: Injuries to the Arm, Hand, Fingertip, and Nail, pp. 101–107"},"extensor-tendon-laceration":{"id":"extensor-tendon-laceration","variants":[{"id":"extensor-main","o":{"T":[{"t":"Clean and irrigate after local anesthesia; tetanus prophylaxis as indicated"},{"t":"Small partial injuries (< 50% transected): absorbable suture material"},{"t":"Larger injuries: 4-0 or 5-0 colorless nonabsorbable suture, figure-of-eight stitch with the knot at the edge of the tendon"},{"t":"Splint the hand or digit in the position of function"},{"t":"Splint in extension for up to 6 weeks or until operative repair","if":"closed DIP tendon injury"}],"Co":[{"t":"Hand specialist (follow-up within 7 days; refer thumb tendons, severe contamination, open DIP injuries)"}]},"name":"Extensor tendon laceration","level":"II","imp":"Extensor tendon laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با پارگی پشت دست و ناتوانی در بازکردن انگشت میانی.","why":"ترمیم ساده توسط پزشک مجرب یا ارجاع؛ اسپلینت در وضعیت عملکردی."}],"ch":"12","name":"Extensor tendon laceration","name_fa":"پارگی تاندون اکستانسور","cc":["wound-bite","limb-injury"],"keywords":"extensor tendon, mallet finger, swan neck, boutonniere, figure-of-eight","status":"draft","features":["پارگی روی مفصل DIP می‌تواند ناهنجاری mallet و در صورت عدم ترمیم swan neck ایجاد کند؛ روی PIP ناهنجاری boutonniere","پارگی باز تاندون DIP نیاز به ترمیم جراحی دارد؛ صدمه بسته باید تا 6 هفته در اکستانسیون اسپلینت شود","پزشک اورژانس مجرب می‌تواند پارگی ساده اکستانسور پشت دست را ترمیم کند"],"ddx":[{"n":"Open DIP tendon laceration","cm":1,"note":"جراحی"},{"n":"Thumb tendon injury","cm":1,"note":"ارجاع"},{"n":"Partial laceration < 50% |"}],"redflags":["آلودگی شدید یا آسیب تاندون شست"],"guide":"بحث با متخصص دست؛ پارگی نسبی کوچک (< 50٪) با بخیه قابل‌جذب؛ بزرگ‌تر با 4-0 یا 5-0 غیرقابل‌جذب بی‌رنگ به‌صورت figure-of-eight با گره در لبه تاندون؛ اسپلینت و پیگیری ظرف 7 روز.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 12: Injuries to the Arm, Hand, Fingertip, and Nail, pp. 101–107"},"flexor-tendon-laceration":{"id":"flexor-tendon-laceration","variants":[{"id":"flexor-main","o":{"T":[{"t":"Clean the wound and suture the overlying skin; splint with the wrist and MCP flexed and PIP and DIP extended","if":"operative repair delayed"},{"t":"Tetanus prophylaxis as indicated"}],"Co":[{"t":"Hand specialist (repair preferably within 24 hours; difficult after 10 to 14 days)"}]},"name":"Flexor tendon laceration","level":"II","imp":"Flexor tendon laceration","cond":"Urgent","act":"RBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مردی ۲۵ ساله با پارگی ولار انگشت اشاره و ناتوانی در خم‌کردن نوک انگشت.","why":"ارجاع فوری به متخصص دست؛ در صورت تأخیر تمیز کردن، دوختن پوست و اسپلینت."}],"ch":"12","name":"Flexor tendon laceration","name_fa":"پارگی تاندون فلکسور","cc":["wound-bite","limb-injury"],"keywords":"flexor tendon, hand surgeon, zone, splint","status":"draft","features":["همه آسیب‌های تاندون فلکسور باید به متخصص دست ارجاع شوند","بسیاری از جراحان ترجیح می‌دهند ظرف 24 ساعت ترمیم کنند؛ بعد از 10 تا 14 روز اسکار و جمع‌شدگی ترمیم را دشوارتر می‌کند"],"ddx":[{"n":"Flexor tendon injury |","cm":1},{"n":"Digital nerve / artery injury |"}],"redflags":["ناتوانی در خم کردن مفاصل"],"guide":"اگر ترمیم جراحی به تأخیر می‌افتد: زخم را تمیز کن و پوست روی آن را بدوز؛ اسپلینت با مچ و MCP فلکسی و PIP/DIP اکستانسیون.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 12: Injuries to the Arm, Hand, Fingertip, and Nail, pp. 101–107"},"finger-fingertip-nail-injury":{"id":"finger-fingertip-nail-injury","variants":[{"id":"finger-lac-amputation","o":{"I":[{"t":"X-ray of the finger (bony injury or foreign body suspected)"}],"T":[{"t":"Finger lacerations: 5-0 nonabsorbable suture; assess for sensory nerve, extensor and flexor tendon injuries"},{"t":"Distal fingertip amputation with skin or pulp loss only: serial dressing changes"},{"t":"Full-thickness skin graft using the severed tip may be considered","if":"without exposed bone"},{"t":"Tetanus prophylaxis as indicated"}],"Co":[{"t":"Hand surgeon (replantation, skin graft)","if":"partial or complete digit amputation, exposed bone, larger skin loss"}]},"name":"Finger laceration or digit amputation","level":"II","imp":"Finger injury","cond":"Urgent","act":"RBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مردی ۳۵ ساله با قطع نوک انگشت بدون استخوان مکشوف در کار با دستگاه.","why":"بر اساس عمق و استخوان مکشوف: ساده تا مشاوره دست."},{"id":"nail-bed-injury","o":{"I":[{"t":"X-ray of the finger","if":"bony injury or fracture suspected"}],"T":[{"t":"Subungual hematoma > 50% of the nail bed: trephination of the nail plate (nail drill, electrocautery, scalpel or 18-gauge needle)"},{"t":"Remove the nail only if nail avulsion or nail fold disruption; repair the nail bed laceration with 6-0 absorbable sutures; clean and trephinate the removed nail and suture it in its anatomic position"},{"t":"Avulsion of the germinal matrix: preserve the fragments and reattach the nail anatomically if possible"},{"t":"Tetanus prophylaxis as indicated"}],"Co":[{"t":"Hand specialist","if":"extensive nail bed injury with avulsed tissue"}]},"name":"Nail bed injury and subungual hematoma","level":"III","imp":"Nail bed injury / subungual hematoma","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۴۰ ساله با درد و هماتوم زیر ناخن بعد از گیرکردن انگشت لای در؛ هماتوم بیش از ۵۰٪ ناخن.","why":"تریفیناسیون ناخن برای هماتوم؛ ترمیم بستر ناخن در پارگی."},{"id":"ring-tourniquet","o":{"T":[{"t":"Ring removal: lubrication, ring cutting, or the string or rubber band technique"}]},"name":"Ring tourniquet syndrome","level":"II","imp":"Ring tourniquet syndrome","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۵۰ ساله با تورم انگشت حلقه بعد از ضربه و گیرکردن حلقه؛ انگشت کبود.","why":"حلقه باید از همه انگشت‌های آسیب‌دیده خارج شود."}],"ch":"12","name":"Finger, fingertip and nail bed injuries (including ring tourniquet)","name_fa":"آسیب انگشت، نوک انگشت و بستر ناخن","cc":["wound-bite","limb-injury"],"keywords":"fingertip amputation, subungual hematoma, nail bed laceration, trephination, ring removal, digital nerve, two-point discrimination","status":"draft","features":["لاسراسیون ساده انگشت با 5-0 غیرقابل‌جذب؛ آسیب عصب حسی یا تاندون را بررسی کن؛ شک به آسیب عصب دیجیتال: تفکیک دو نقطه > 10 mm یا بیشتر در یک طرف پد ولار","قطع نوک انگشت فقط پوست یا پالپ: درمان محافظه‌کارانه با تعویض پانسمان؛ استخوان مکشوف: گرافت پوست مناسب نیست و نیاز به متخصص","هماتوم زیر ناخن > 50٪: تریفیناسیون ناخن نتیجه خوب می‌دهد","آواسیون بستر ناخن بدترین پیش‌آگهی را در آسیب‌های نوک انگشت دارد","ring tourniquet: حلقه تنگ حول فالانکس پروگزیمال به‌دلیل تورم دیستال گیر می‌کند؛ حلقه را از همه انگشتان آسیب‌دیده بردار"],"ddx":[{"n":"Digital nerve injury |","cm":1},{"n":"Partial or complete digit amputation |","cm":1},{"n":"Nail bed laceration / avulsion |"},{"n":"Ring tourniquet syndrome |"}],"redflags":["قطع انگشت (مشاوره برای ری‌پلانت)","استخوان مکشوف"],"guide":"تریفیناسیون با drill ناخن، الکتروکوتر، اسکالپل یا سوزن 18. ناخن را فقط در آواسیون ناخن یا از هم گسیختگی نیل فولد بردار. بستر ناخن با 6-0 قابل‌جذب ترمیم می‌شود و ناخن تمیز و سوراخ‌شده در موقعیت آناتومیک ثابت می‌شود. روش‌های برداشتن حلقه: روان‌کننده، برش حلقه، روش نخ یا کش لاستیکی.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 12: Injuries to the Arm, Hand, Fingertip, and Nail, pp. 101–107"},"leg-foot-laceration":{"id":"leg-foot-laceration","variants":[{"id":"leg-foot-simple","o":{"I":[{"t":"X-ray; ultrasonography for foreign body, tendon injury or bone abnormality","if":"fracture or radiopaque foreign body suspected"}],"T":[{"t":"Thorough wound exploration and irrigation; evaluate distal motor and sensory function compared with the contralateral side"},{"t":"Layered closure with 4-0 absorbable material to close the fascia and interrupted 4-0 nonabsorbable sutures for the skin (not typically required on the foot); avoid deep absorbable sutures in diabetes, immunocompromise or venous stasis changes"},{"t":"Update tetanus immunization status"},{"t":"Wound care instructions; elevation; suture removal in 10 to 14 days (14 days over joints); recheck at 48 hours for heavily contaminated, complex repair or higher infection risk; crutches for 7 to 10 days as needed"}]},"name":"Uncomplicated leg or foot laceration","level":"III","imp":"Leg / foot laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با پارگی ۴ سانتی‌متری ساق بعد از برخورد با فلز؛ تاندون و عصب سالم.","why":"پس از رد آسیب عمقی، شستشو و ترمیم لایه‌ای؛ آنتی‌بیوتیک روتین لازم نیست."},{"id":"foot-sole-laceration","o":{"I":[{"t":"X-ray; ultrasonography","if":"fracture or radiopaque foreign body suspected"}],"T":[{"t":"Patient prone with the foot supported on a pillow or overhanging the bed; regional anesthesia helps"},{"t":"Repair as soon as possible, ideally within 6 hours; wounds presenting between 6 and 12 hours can often be repaired primarily"},{"t":"Nonabsorbable 3-0 or 4-0 suture for the sole (large needle); 4-0 or 5-0 nonabsorbable for the dorsal foot; between toes: assistant holds toes apart, interrupted mattress suture may help"},{"t":"Crutches and/or walking boot after repair"},{"t":"Update tetanus immunization status"}],"Co":[{"t":"Orthopedics","if":"severe lawn mower or bicycle spoke injuries with fractures and tendon lacerations"}]},"name":"Foot and sole laceration","level":"III","imp":"Foot laceration","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۵ ساله با پارگی کف پا از میخ‌ شکسته ۳ ساعت پیش؛ پا حس دارد.","why":"کف پا را از نظر تاندون و جسم خارجی بررسی کن؛ بخیه ضخیم‌تر و بی‌حسی ناحیه‌ای."},{"id":"knee-ankle-laceration","o":{"I":[{"t":"X-ray of the knee (air in the joint)"}],"A":[{"t":"Antibiotics","if":"tendon or joint involvement, heavily contaminated, bite, open fracture, early infection","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"Examine the knee throughout its range of movement; assess patellar and quadriceps tendon function; assess for popliteal artery, popliteal nerve and tibial nerve injury"},{"t":"Inject 65 to 95 mL of sterile saline into the joint at a site separate from the laceration: leakage from the wound indicates capsule injury","if":"joint penetration test"},{"t":"Ankle: move through full range of motion and directly inspect for tendon injury (Achilles, tibialis anterior, extensor hallucis longus: repair if injured); Thompson test: squeeze the calf at the midpoint, absent plantar flexion means complete Achilles laceration"},{"t":"Splint in a position of function after repair of joint or tendon lacerations"},{"t":"Update tetanus immunization status"}],"Co":[{"t":"Orthopedics (tendon repair, joint involvement)"}]},"name":"Knee or ankle laceration (joint or tendon concern)","level":"II","imp":"Knee / ankle laceration","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زنی ۴۰ ساله با پارگی جلوی زانو بعد از افتادن روی شیشه؛ احتمال نفوذ به مفصل.","why":"بررسی نفوذ به کپسول مفصل، تاندون‌ها و عروق؛ آنتی‌بیوتیک در درگیری مفصل یا تاندون."}],"ch":"13","name":"Leg, knee, ankle and foot lacerations","name_fa":"پارگی ساق، زانو، مچ پا و پا","cc":["wound-bite","limb-injury"],"keywords":"foot laceration, plantar laceration, Achilles tendon, Thompson test, knee joint capsule, saline load test, crutches, walking boot","status":"draft","features":["مکانیسم احتمال آسیب بافت زیرین، جسم خارجی و آلودگی را تعیین می‌کند؛ موقعیت اندام هنگام آسیب را در معاینه بازسازی کن","اعصاب: peroneal سطحی (اورژن)، peroneal عمقی (اینورژن و دورسی‌فلکشن)، تیبیال (پلانتارفلکشن)","تاندون‌ها: extensor hallucis longus، tibialis anterior، آشیل؛ هر تاندون را جداگانه آزمایش کن","آزمایش‌های آزمایشگاهی در لاسراسیون ساده لازم نیست؛ X-ray برای شک به شکستگی یا جسم رادیواپک؛ سونوگرافی برای جسم خارجی، تاندون یا استخوان","زانو: نفوذ به کپسول مفصل (هوا در X-ray، یا تزریق 65 تا 95 mL سالین استریل در مفصل از محل جدا و نشت از زخم)","آشیل: پارگی بدون نفوذ هم ممکن است؛ آزمون Thompson (فشردن ساق: نبود پلانتارفلکشن یعنی پارگی کامل)","پا: ترمیم ایده‌آل در 6 ساعت؛ بین 6 تا 12 ساعت اغلب اولیه"],"ddx":[{"n":"Tendon injury (Achilles, tibialis anterior, EHL) |","cm":1},{"n":"Joint capsule penetration (knee) |","cm":1},{"n":"Popliteal artery / nerve injury |","cm":1},{"n":"Retained foreign body |"},{"n":"Open fracture |"}],"redflags":["نفوذ به مفصل یا تاندون","زخم‌های آلوده شدید، گزش، شکستگی باز"],"guide":"ترمیم لایه‌ای با 4-0 قابل‌جذب (فاشیا) و 4-0 غیرقابل‌جذب منقطع (پوست) روی ساق؛ بخیه عمقی قابل‌جذب در دیابت، نقص ایمنی و استاز وریدی پرهیز؛ چسب سیانوآکریلات کمتر (کشش بیشتر). پوست کف پا: 3-0 یا 4-0 غیرقابل‌جذب؛ پشت پا 4-0 یا 5-0. بعد از ترمیم لاسراسیون مفصل یا تاندون: اسپلینت در وضعیت عملکردی. کشیدن بخیه 10–14 روز (14 روز روی مفصل).","pearls":["آنتی‌بیوتیک: شکستگی باز، درگیری تاندون یا مفصل، آلودگی شدید، گزش، بیماران پرخطر و زخم با نشانه زودرس عفونت.","قیچی چمن‌زن و پره دوچرخه ممکن است آسیب بافت نرم گسترده با شکستگی و پارگی تاندون بدهند: ارتوپدی."],"section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 13: Lacerations to the Leg and Foot, pp. 108–111"},"hair-thread-tourniquet":{"id":"hair-thread-tourniquet","variants":[{"id":"hair-tourniquet-main","o":{"T":[{"t":"Remove the hair or thread completely, unwinding it if possible; otherwise a midline longitudinal incision along the extensor surface of the toe to cut the hair or thread"}]},"name":"Hair-thread tourniquet of a toe","level":"II","imp":"Hair-thread tourniquet syndrome","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"شیرخواری ۳ ماهه با گریه و قرمزی و تورم انگشت پا؛ دور انگشت تار مو دیده می‌شود.","why":"برداشتن کامل مو یا نخ برای رفع انسداد جریان خون."}],"ch":"13","name":"Hair-thread tourniquet syndrome","name_fa":"سندرم تورنیکت مو یا نخ","cc":["pediatric-other","limb-injury"],"keywords":"hair tourniquet, toe, infant, thread","status":"draft","features":["آسیب نادر شیرخواران: تار مو یا نخ بلند دور یک انگشت پا پیچیده و می‌تواند باعث نقص عروقی شود"],"ddx":[{"n":"Vascular compromise of the toe |","cm":1},{"n":"Toe infection / cellulitis |"}],"redflags":["ایسکمی انگشت"],"guide":"مو یا نخ را کامل برداشته تا نقص عصبی‌عروقی برطرف شود.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 13: Lacerations to the Leg and Foot, pp. 108–111"},"soft-tissue-foreign-body":{"id":"soft-tissue-foreign-body","variants":[{"id":"fb-general","o":{"I":[{"t":"Plain radiograph (underpenetrated soft tissue technique); CT, ultrasound or MRI in some circumstances (wood: ultrasound/CT/MRI better; metal and glass: plain film excellent)","if":"foreign body suspected and not identified by inspection"}],"T":[{"t":"Adequate lighting, anesthesia and hemostasis; inspect all recesses; extend the wound margins with a scalpel if needed; blind gentle probing with a closed hemostat (glass)"},{"t":"Remove the foreign body (consider referral to a specialist for complicated or delayed removal)"},{"t":"Tetanus immunization and appropriate wound care; primary closure after removal if infection risk is low, delayed primary closure for higher risk"},{"t":"No proven benefit of prophylactic antibiotics for wounds that are not infected"}]},"name":"Retained foreign body (assessment and removal)","level":"III","imp":"Soft tissue foreign body","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۵ ساله با فرورفتن خرده شیشه در کف دست و احساس جسم خارجی.","why":"شناسایی با اکتشاف و تصویربرداری و سپس تصمیم برای برداشتن یا باقی گذاشتن."},{"id":"fb-needle-splinter","o":{"T":[{"t":"Superficial metallic needle: small incision over one end and remove with a hemostat; deeper: incision at the midpoint, grasp with a hemostat and push it out through the entrance wound; perpendicular needle: extend the incision and press the wound edges to expose it"},{"t":"Small superficial wood splinter or spine: forceps; deeper: incision along the long axis of the foreign body; small and hard to localize: remove a small elliptical block of tissue and close primarily; subungual splinter: traction or excise a portion of nail over it"},{"t":"Cactus spines in the dermis: remove individually or apply adhesive (facial gel, rubber cement, household glue) and peel when dry"},{"t":"Fishhook (after anesthesia): retrograde technique; string-pull method; advance-and-cut (push the point and barb through, clip with wire cutters, thread the rest back); incision technique (nearly always successful)"}]},"name":"Needle, wood splinter, spine, fishhook","level":"III","imp":"Foreign body: needle / splinter / fishhook","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودکی ۱۰ ساله با فرورفتن خرده چوب زیر ناخن؛ یا مردی ۴۰ ساله با قلاب ماهیگیری در انگشت.","why":"روش برداشتن بر اساس نوع جسم و محل آن."}],"ch":"14","name":"Soft tissue foreign body","name_fa":"جسم خارجی بافت نرم","cc":["wound-bite","limb-injury"],"keywords":"foreign body, splinter, needle, fishhook, glass, thorn, cactus spine, ultrasound, removal","status":"draft","features":["فقط درصد کمی از لاسراسیون‌ها و زخم‌های نافذ جسم خارجی دارند؛ مکانیسم، جنس و شکل جسم و محل زخم را بررسی کن","اجسام شکننده (خار، شاخه) پیش از شکستن عمیق نفوذ می‌کنند؛ خرده چوب هنگام کشیدن اغلب خرد می‌شود","احساس جسم خارجی در بالغ بیش از دو برابر احتمال وجود آن را بالا می‌برد؛ زخم ترمیم‌شده با درد تیز با حرکت، ترمیم ضعیف، عفونت راجعه یا توده بافت نرم نشانه جسم ناشناخته است","زخم عمیق‌تر از 5 mm یا با عمق غیرقابل‌دید ارتباط بیشتر با جسم خارجی دارد","تصویربرداری: فلز و شیشه در X-ray عالی؛ چوب و خار ضعیف (سونوگرافی، CT یا MRI مناسب‌تر). سونوگرافی > 90٪ حساس برای اجسام بزرگ‌تر از 4 تا 5 mm"],"ddx":[{"n":"Retained foreign body in a healed wound |","cm":1},{"n":"Infection from retained organic material |","cm":1},{"n":"Soft tissue mass |"}],"redflags":["عفونت راجعه یا زخم غیرترمیم‌شونده"],"guide":"همه اجسام نیاز به خارج‌کردن ندارند: کوچک، بی‌اثر، عمیق و بدون علامت را می‌توان باقی گذاشت. خار، خرده چوب، ستون گیاهی یا اجسام آلوده سریع‌تر برداشته شوند. آنتی‌بیوتیک پروفیلاکسی برای زخم عفونی‌نشده فایده اثبات‌شده ندارد.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 14: Soft Tissue Foreign Bodies, pp. 112–114"},"puncture-wound":{"id":"puncture-wound","variants":[{"id":"puncture-clean","o":{"I":[{"t":"Plain radiographs; CT scan if a foreign body is still suspected after a negative plain film","if":"suspicion of fracture, infected wound, materials prone to fragment (wood, glass), foreign body sensation"}],"T":[{"t":"Superficial wound cleansing; tetanus prophylaxis as indicated (soaking and coring of the tract have no proven benefit)"}]},"name":"Uncomplicated clean puncture wound (< 6 hours)","level":"III","imp":"Puncture wound","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با پانکچر کف پا ۳ ساعت پیش از میخ تمیز؛ بدون احساس جسم خارجی.","why":"پانکچر تمیز زیر 6 ساعت: تمیزکردن سطحی و کزاز؛ آنتی‌بیوتیک روتین لازم نیست."},{"id":"puncture-high-risk","o":{"I":[{"t":"Plain radiograph (retained foreign body)"}],"A":[{"t":"A first-generation cephalosporin, anti-staphylococcal penicillin, or macrolide for most punctures where antibiotics are prescribed","fl":[{"k":"note","v":"doses not given in the book"}]},{"t":"Ciprofloxacin 500 mg PO twice daily (anti-pseudomonal)","if":"plantar puncture through an athletic shoe"}],"T":[{"t":"Superficial wound cleansing; tetanus prophylaxis as indicated"}]},"name":"High-risk plantar puncture (diabetes, athletic shoe, forefoot)","level":"II","imp":"Plantar puncture wound, high risk","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۵۵ ساله دیابتی با پانکچر جلوی پا از میخ در کفش ورزشی ۱۲ ساعت پیش.","why":"در بیمار پرخطر یا پانکچر از کفش ورزشی پروفیلاکسی آنتی‌بیوتیکی همراه تمیزکردن و کزاز توصیه می‌شود."},{"id":"puncture-cellulitis-abscess","o":{"A":[{"t":"7- to 10-day course of a first-generation cephalosporin, anti-staphylococcal penicillin, trimethoprim-sulfamethoxazole, or clindamycin","if":"cellulitis","fl":[{"k":"note","v":"doses not given in the book"}]},{"t":"Antibiotics typically only if surrounding cellulitis","if":"abscess"}],"T":[{"t":"Incision, drainage and careful exploration for a retained foreign body","if":"abscess"}]},"name":"Cellulitis or abscess after a puncture wound","level":"II","imp":"Cellulitis / abscess after puncture wound","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۴۰ ساله ۳ روز بعد از پانکچر پا با قرمزی و تورم موضعی بدون ترشح زیاد؛ یا تجمع چرک در محل.","why":"سلولیت موضعی با آنتی‌بیوتیک 7 تا 10 روز؛ آبسه با برش و تخلیه و جستجوی جسم خارجی."},{"id":"puncture-osteomyelitis","o":{"I":[{"t":"MRI (most commonly used modality from the ED)"}],"L":[{"t":"ESR, CRP"}],"Co":[{"t":"Surgery (timing of IV antibiotics and admission for surgical treatment)"}]},"name":"Osteomyelitis after puncture wound","level":"I","imp":"Osteomyelitis after puncture wound","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"پسری ۱۴ ساله ۱۰ روز بعد از پانکچر از کفش ورزشی با درد پایدار و تورم جلوی پا؛ X-ray طبیعی.","why":"در مراحل اولیه X-ray طبیعی است؛ ESR/CRP و MRI کمک می‌کند؛ مشاوره جراحی و آنتی‌بیوتیک وریدی."}],"ch":"15","name":"Puncture wounds (including cellulitis, abscess and osteomyelitis)","name_fa":"زخم‌های نافذ (پانکچر)","cc":["wound-bite","limb-injury"],"keywords":"puncture wound, plantar puncture, nail, athletic shoe, Pseudomonas, osteomyelitis, ciprofloxacin, cephalosporin","status":"draft","features":["تمیزکردن و دیدن کل عمق دشوار است؛ شایع روی کف پا؛ شامل آسیب با تجهیزات تزریق فشار بالا و سوزن","عفونت در 6 تا 11٪؛ S. aureus (از جمله MRSA) غالب؛ Pseudomonas شایع‌ترین عامل استئومیلیت بعد از پانکچر از کفش ورزشی","درمان بعد از بیش از 6 ساعت خطر عفونت بیشتر؛ چوب، شیشه و پلاستیک ممکن است خرد شوند","عفونت علی‌رغم آنتی‌بیوتیک: شک به جسم خارجی باقی‌مانده","علائم عفونت: درد قابل‌توجه، تورم، قرمزی، گرمی، فلوکتواسیون، کاهش دامنه حرکت یا ترشح"],"ddx":[{"n":"Retained foreign body |","cm":1},{"n":"Osteomyelitis (> 7 days after injury) |","cm":1},{"n":"Cellulitis |"},{"n":"Local abscess |"}],"redflags":["دیابت یا نقص ایمنی، پانکچر forefoot از کفش ورزشی","درد پایدار، شک به عفونت فضای عمقی یا عدم پاسخ به درمان"],"guide":"پانکچر تمیز زیر 6 ساعت بدون جسم خارجی: تمیزکردن سطحی و پروفیلاکسی کزاز؛ خیساندن، دبریدمان یا coring فایده ندارد و آنتی‌بیوتیک روتین توصیه نمی‌شود. بیمار پرخطر با پانکچر کف پا: آنتی‌بیوتیک پروفیلاکسی. سلولیت: 7 تا 10 روز. آبسه: برش و تخلیه و جستجوی جسم خارجی. استئومیلیت: مشاوره جراحی و آنتی‌بیوتیک وریدی.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 15: Puncture Wounds and Bites, pp. 115–120"},"needle-stick-injury":{"id":"needle-stick-injury","variants":[{"id":"needlestick-main","o":{"T":[{"t":"Evaluation, testing and treatment per the hospital's predesigned needle-stick protocol (including hepatitis B and HIV prophylaxis)","fl":[{"k":"note","v":"regimens not given in the book"}]}]},"name":"Needle-stick injury","level":"II","imp":"Needle-stick injury","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"پرستاری ۲۸ ساله با فرورفتن سوزن آلوده به خون بیمار شناخته‌شده با هپاتیت C در دست.","why":"ارزیابی، آزمایش و پروفیلاکسی طبق پروتکل بیمارستان."}],"ch":"15","name":"Needle-stick injury","name_fa":"آسیب سوزن‌ خوردن","cc":["wound-bite"],"keywords":"needlestick, hepatitis B, hepatitis C, HIV, post-exposure prophylaxis, health care worker","status":"draft","features":["نگرانی اصلی در کادر درمان از قرار گرفتن در معرض هپاتیت و HIV است","خطر عفونت پس از آسیب با منبع آلوده: هپاتیت A ناچیز، هپاتیت B حدود 6٪، هپاتیت C حدود 2٪ و HIV حدود 0.3٪","توصیه‌ها پیچیده و در حال تغییر است"],"ddx":[{"n":"Hepatitis B / C exposure |","cm":1},{"n":"HIV exposure |","cm":1}],"redflags":["منبع شناخته‌شده HIV یا هپاتیت"],"guide":"هر بیمارستان باید پروتکل از پیش طراحی‌شده توسط متخصصان عفونی برای ارزیابی، آزمایش و درمان (از جمله پروفیلاکسی هپاتیت B و HIV) داشته باشد.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 15: Puncture Wounds and Bites, pp. 115–120"},"high-pressure-injection-injury":{"id":"high-pressure-injection-injury","variants":[{"id":"hpi-main","o":{"I":[{"t":"X-ray of the hand","fl":[{"k":"note","v":"not stated in the book; used to see radiopaque material"}]}],"T":[{"t":"Parenteral analgesics ; avoid digital blocks with local anesthesia","fl":[{"k":"note","v":"agent and dose not given in the book"},{"k":"ci","v":"digital block increases tissue pressure"}]}],"Co":[{"t":"Hand specialist (early surgical debridement)"}]},"name":"High-pressure injection injury","level":"I","imp":"High-pressure injection injury","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۳۵ ساله کارگر با تزریق گریس به نوک انگشت اشاره با اسپری صنعتی؛ درد و تورم خفیف.","why":"علی‌رغم ظاهر خفیف جدی است؛ مسکن تزریقی، پرهیز از بلوک دیجیتال و مشاوره دست."}],"ch":"15","name":"High-pressure injection injury","name_fa":"آسیب تزریق فشار بالا","cc":["wound-bite","limb-injury"],"keywords":"grease gun, paint gun, high pressure injection, hand surgery, digital block","status":"draft","features":["ممکن است به‌صورت زخم نافذ ظاهر شود، معمولاً در دست یا پا؛ ناشی از تجهیزات صنعتی که گریس، رنگ یا مایع را با فشار بالا تزریق می‌کنند","ابتدا درد با تورم کم؛ اما شدید است چون مایع در امتداد صفحات فاسیال پخش و واکنش التهابی تأخیری ایجاد می‌کند"],"ddx":[{"n":"Deep fascial spread of injected material |","cm":1},{"n":"Simple puncture wound |"}],"redflags":["هر آسیب تزریق فشار بالا (جراحی فوری دست)"],"guide":"درد را با مسکن تزریقی کنترل کن و از بلوک دیجیتال با بی‌حسی موضعی پرهیز کن (فشار بافت را بیشتر می‌کند). مشاوره متخصص دست برای دبریدمان زودهنگام.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 15: Puncture Wounds and Bites, pp. 115–120"},"epinephrine-autoinjector-injury":{"id":"epinephrine-autoinjector-injury","variants":[{"id":"epi-injury-main","o":{"T":[{"t":"Supportive care"},{"t":"Phentolamine 0.5 mL of standard solution (5 mg/mL) mixed with 0.5 mL of 1% lidocaine (1 mL total containing 2.5 mg phentolamine) subcutaneously, injected directly through the autoinjector puncture site","if":"digital ischemia"}]},"name":"Accidental epinephrine injection into a digit","level":"III","imp":"Epinephrine autoinjector injury","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۰ ساله هنگام تزریق اتواینجکتور آنافیلاکسی به انگشت خود تزریق کرد؛ انگشت سفید و سرد.","why":"حمایتی؛ در ایسکمی فنتولامین زیرجلدی."}],"ch":"15","name":"Epinephrine autoinjector injury (accidental digit injection)","name_fa":"تزریق تصادفی اپی‌نفرین به انگشت","cc":["wound-bite","limb-injury"],"keywords":"EpiPen, phentolamine, digital ischemia, vasospasm","status":"draft","features":["تزریق ناخواسته اپی‌نفرین به دست یا انگشت حین درمان واکنش آلرژیک","درد سوزن، پارستزی و وازواسپاسم؛ در انگشت ممکن است کل انگشت رنگ‌پریده و سرد باشد","شواهد روشنی که درمان فعال بهتر از مشاهده باشد وجود ندارد"],"ddx":[{"n":"Digital ischemia |","cm":1},{"n":"Needle stick pain only |"}],"redflags":["ایسکمی ادامه‌دار انگشت"],"guide":"بسیاری با مراقبت حمایتی بهبود می‌یابند؛ فنتولامین زیرجلدی در محل پانکچر تنها درمانی است که به‌طور مداوم ایسکمی را سریع برمی‌گرداند. بعد از رفع ایسکمی ترخیص (عود بعید است).","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 15: Puncture Wounds and Bites, pp. 115–120"},"mammalian-bites":{"id":"mammalian-bites","variants":[{"id":"bite-dog-cat","o":{"I":[{"t":"X-ray","if":"joint or tendon concern, fracture"}],"A":[{"t":"Amoxicillin-clavulanate 500 to 800 mg PO twice daily (most commonly recommended for local infection and prophylaxis after dog or cat bites)"},{"t":"Penicillin V 500 mg four times daily or Ampicillin 500 mg four times daily (Pasteurella multocida)","if":"lower-cost alternative for cat bites"},{"t":"Azithromycin 5-day course; [immunosuppressed] 7- to 10-day course of trimethoprim-sulfamethoxazole, ciprofloxacin, or rifampin","if":"cat-scratch lymphadenopathy, severe painful"},{"t":"Cephalexin, dicloxacillin, erythromycin or clindamycin alone are likely not sufficient"}],"T":[{"t":"Examine, clean with irrigation, debride as necessary; evaluate joints and tendons"},{"t":"Consider primary closure for low-risk wounds after careful assessment and irrigation; avoid primary closure in immunodeficiency or comorbidities; high-risk wounds: clean, debride and dress moist; reevaluate in 24 to 48 hours"},{"t":"Tetanus and/or rabies prophylaxis as indicated (see tetanus and rabies)"}]},"name":"Dog or cat bite","level":"II","imp":"Dog / cat bite","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۵ ساله با گزش گربه روی دست چپ و پانکچر عمیق، بدون علائم عفونت.","why":"گزش گربه، دست، عمیق یا نقص ایمنی خطر عفونت بالا دارد؛ آنتی‌بیوتیک پروفیلاکسی."},{"id":"bite-human","o":{"A":[{"t":"Amoxicillin-clavulanate (prophylactic)"},{"t":"Ampicillin-sulbactam, cefoxitin, or piperacillin-tazobactam","if":"infections requiring parenteral antibiotics","fl":[{"k":"note","v":"doses not given in the book"}]},{"t":"Acyclovir or valacyclovir","if":"herpetic whitlow"}],"T":[{"t":"Clean and irrigate; suture repair typically not advised (possible exception facial wounds)"},{"t":"Tetanus prophylaxis as indicated"}]},"name":"Human bite","level":"II","imp":"Human bite","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۵ ساله با زخم گاز گرفته شدن روی بازو در دعوا.","why":"گزش انسان پلی‌میکروبی؛ آموکسی‌سیلین–کلاولانات پروفیلاکتیک و معمولاً بدون بخیه."},{"id":"bite-other","o":{"A":[{"t":"Rats, mice, squirrels, gerbils (Streptobacillus moniliformis / Spirillum minus): Amoxicillin-clavulanate"},{"t":"Livestock and large game animals (Brucella, Leptospira, Francisella tularensis): Amoxicillin-clavulanate or specific agent for the disease; broad-spectrum prophylactic antibiotics"},{"t":"Monkeys (herpes B virus): Acyclovir or valacyclovir"},{"t":"Freshwater fish (Aeromonas): Fluoroquinolone or trimethoprim-sulfamethoxazole; saltwater fish (Vibrio): Fluoroquinolone"}],"T":[{"t":"Aggressive wound care; rodent bites: standard wound care (rodents are not known to carry rabies)"},{"t":"Rabies immune globulin and rabies vaccine","if":"bats, dogs, skunks, raccoons, foxes and other carnivores, monkeys"}]},"name":"Rodent, livestock, wild animal, freshwater or saltwater fish","level":"II","imp":"Animal bite","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۵ ساله دامدار با گزش گاو و زخم عمیق؛ یا مردی با گزش جونده.","why":"گزش جونده تیمار ساده؛ دام و حیوانات بزرگ: مراقبت زخم تهاجمی و آنتی‌بیوتیک پروفیلاکتیک وسیع‌الطیف."}],"ch":"15","name":"Mammalian bites (dog, cat, human, rodent, livestock, other)","name_fa":"گزش پستانداران","cc":["wound-bite"],"keywords":"dog bite, cat bite, human bite, rodent, livestock, amoxicillin-clavulanate, Pasteurella, Capnocytophaga, rabies, cat-scratch, Bartonella, herpes B, Eikenella","status":"draft","features":["عوارض: آسیب بافتی خود گزش، عفونت موضعی یا بیماری سیستمیک؛ همه زخم‌ها شستشو و در صورت لزوم دبریدمان شوند؛ آسیب مفصل یا تاندون را بررسی کن؛ نیاز به کزاز یا هاری را ارزیابی کن","زخم‌های کم‌خطر اغلب بسته می‌شوند؛ صورت و سر بدون بافت غیرزنده و بدون شکستگی، در ایمنی طبیعی کاندید بستن اولیه؛ پرخطر: ترمیم تأخیری","گزش سگ: اغلب سطحی با خطر عفونت حدود 5٪؛ گزش گربه: پانکچر عمیق‌تر و عفونت تا 80٪ (واقعی احتمالاً کمتر)","گزش انسان: عفونت پلی‌میکروبی (استافیلوکوک، استرپتوکوک، Eikenella)؛ معمولاً بخیه توصیه نمی‌شود (احتمالاً بجز صورت)","گزش جونده: بی‌اهمیت؛ جونده‌ها هاری را حمل نمی‌کنند. دام و حیوانات بزرگ شکاری: خطر بروسلوز، لپتوسپیروز، تولارمی","Capnocytophaga canimorsus: بیماری باکتریمیک نادر و مهاجم بعد از گزش سگ (الکلی، بدون طحال، سرکوب ایمنی)"],"ddx":[{"n":"Rabies exposure (bats, dogs, skunks, raccoons, foxes, monkeys) |","cm":1},{"n":"Capnocytophaga sepsis |","cm":1},{"n":"Joint / tendon injury |"},{"n":"Cat-scratch disease (Bartonella henselae) |"},{"n":"Herpes B (monkey bites) |"}],"redflags":["گزش پرخطر در بیمار با نقص ایمنی، دست، گربه یا انسان","نشانه‌های عفونت سیستمیک"],"guide":"آنتی‌بیوتیک پروفیلاکسی: گزش انسان و گزش پرخطر (گربه، سگ عمیق، دست، نیاز به دبریدمان، نقص ایمنی). خط اول معمولاً آموکسی‌سیلین–کلاولانات. سفالکسین، دی‌کلوکساسیلین، اریترومایسین یا کلیندامایسین به‌تنهایی برای Pasteurella کافی نیستند.","pearls":["بازبینی زخم پرخطر در 24 تا 48 ساعت.","بیماری خراش گربه: لنفادنوپاتی 7 تا 12 روز بعد؛ اغلب فقط حمایتی."],"section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 15: Puncture Wounds and Bites, pp. 115–120"},"postrepair-wound-care":{"id":"postrepair-wound-care","variants":[{"id":"postrepair-routine","o":{"N":[{"t":"Protective nonadherent dressing for 24 to 48 hours (or a semipermeable film); elevate the injured part; splint for extremity injuries; pressure dressing for ear and scalp lacerations"},{"t":"Cleanse sutured or stapled wounds with soap and water from 8 hours after closure; examine daily for infection"}],"T":[{"t":"Topical antibiotic ointment (not on wounds closed with tissue adhesive; adhesive wounds may shower but not be immersed)","if":"optional, to promote moist healing and limit scab formation, first 3 to 5 days"},{"t":"Short course of analgesics (narcotics rarely necessary after the first 48 hours)"},{"t":"Tetanus prophylaxis as indicated (see tetanus prophylaxis for wounds)"},{"t":"Suture removal: face 3 to 5 days; most other areas 7 to 10 days; hands, feet, buttocks, over joints 10 to 14 days; sunblock for at least 6 to 12 months"}]},"name":"Routine postrepair care","level":"III","imp":"Postrepair wound care","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله بعد از بخیه زخم ساعد؛ می‌خواهد بداند چطور مراقبت کند.","why":"پانسمان، بالا نگه‌داشتن، شستشو، بازبینی و زمان کشیدن بخیه."},{"id":"postrepair-high-risk","o":{"A":[{"t":"Uncomplicated patient: first-generation cephalosporin or antistaphylococcal penicillin (alternative macrolide or clindamycin)"},{"t":"Grossly contaminated wounds and/or retained foreign body: amoxicillin/clavulanate or second-generation cephalosporin (alternative clindamycin plus a fluoroquinolone)"},{"t":"Bite wounds: amoxicillin/clavulanate (alternative clindamycin plus a fluoroquinolone or trimethoprim-sulfamethoxazole)"},{"t":"Plantar puncture wounds: ciprofloxacin (alternative first-generation cephalosporin or antistaphylococcal penicillin)"},{"t":"Systemic immunodeficiency (AIDS, chronic steroid use, poorly controlled diabetes): amoxicillin/clavulanate or second-generation cephalosporin (alternative clindamycin plus a fluoroquinolone)"},{"t":"Impaired local defenses (peripheral arterial disease, lymphedema): amoxicillin/clavulanate (alternative clindamycin or erythromycin)"},{"t":"Course: 3 to 5 days for nonbite injuries, 5 to 7 days for bite wounds","fl":[{"k":"note","v":"doses not given in the book"}]}],"T":[{"t":"Return for a wound check in 24 to 48 hours"},{"t":"Drain or ribbon gauze packing for abscess cavities or contaminated areas as indicated, with follow-up instructions"}]},"name":"High-risk wound (antibiotic prophylaxis)","level":"II","imp":"Postrepair prophylaxis in a high-risk wound","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۵۸ ساله دیابتی با پارگی پای آلوده که ترمیم شده است.","why":"فقط در شرایط خاص آنتی‌بیوتیک پروفیلاکتیک 3 تا 5 روز (غیرگزش) یا 5 تا 7 روز (گزش) و بازبینی 24 تا 48 ساعت."}],"ch":"16","name":"Postrepair wound care and follow-up","name_fa":"مراقبت بعد از ترمیم زخم","cc":["wound-bite"],"keywords":"dressing, suture removal, topical antibiotic, wound drain, packing, follow-up, sunblock, postrepair antibiotics","status":"draft","features":["پانسمان محیط مرطوب برای اپیتلیالیزاسیون فراهم می‌کند؛ زخم بخیه یا استیپل با پانسمان محافظ و نچسب 24 تا 48 ساعت","زخم با چسب بافتی نباید مرهم آنتی‌بیوتیک بگیرد (چسب شل و باز شدن زخم)","بالا نگه‌داشتن عضو، اسپلینت، پانسمان فشاری (گوش و پوست سر)","آنتی‌بیوتیک روتین توصیه نمی‌شود؛ دوره 3 تا 5 روز برای غیرگزش و 5 تا 7 روز برای گزش","شستشوی زخم بخیه‌شده از 8 ساعت بعد بدون افزایش عفونت؛ روزانه علائم عفونت را بررسی کن","بخیه صورت 3 تا 5 روز؛ سایر نواحی 7 تا 10 روز؛ دست، پا، باسن یا روی مفصل 10 تا 14 روز","اسکار همیشه ایجاد می‌شود؛ پرهیز از آفتاب و ضدآفتاب حداقل 6 تا 12 ماه"],"ddx":[{"n":"Wound infection |","cm":1},{"n":"Dehiscence after suture removal |","cm":1},{"n":"Allergy to topical agent |"}],"redflags":["قرمزی، ترشح یا درد بیشتر: برگشت فوری"],"guide":"بازبینی در 24 تا 48 ساعت برای زخم پرخطر یا بیماری همراه. کشیدن بخیه: بدون کشش عمود بر زخم؛ گره را با فورسپس بگیر و ببر؛ استیپل با ابزار مخصوص. چسب بافتی خودبه‌خود ظرف 5 تا 10 روز می‌ریزد. مخدر بعد از 48 ساعت اول به‌ندرت لازم است.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 16: Postrepair Wound Care, pp. 121–124"},"tetanus-prophylaxis-wound":{"id":"tetanus-prophylaxis-wound","variants":[{"id":"tetanus-under-3-doses","o":{"T":[{"t":"Tetanus toxoid (Tdap if adult and no prior record; Td if > 7 years; DT if < 7 years), preferably in the deltoid"},{"t":"Tetanus immune globulin (TIG) 250 to 500 IU in the deltoid opposite the toxoid site","if":"all other wounds: delayed > 6 h, deep > 1 cm, grossly contaminated, saliva or feces, stellate, ischemic or infected, avulsion, puncture, crush"},{"t":"No TIG","if":"clean minor wound"}]},"name":"Fewer than 3 doses or uncertain history","level":"III","imp":"Wound, tetanus prophylaxis (< 3 doses or uncertain)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۰ ساله مهاجر بدون سابقه واکسیناسیون با پارگی عمیق آلوده.","why":"با کمتر از 3 دوز یا نامشخص: همیشه توکسوئید و در «سایر زخم‌ها» TIG هم."},{"id":"tetanus-3-or-more-doses","o":{"T":[{"t":"Last dose within 5 years: no toxoid, no TIG (clean minor or all other wounds)"},{"t":"Last dose 5 to 10 years: no toxoid for clean minor wounds; tetanus toxoid for all other wounds; no TIG"},{"t":"Last dose more than 10 years: tetanus toxoid for clean minor wounds and for all other wounds; no TIG"}]},"name":"Three or more doses","level":"III","imp":"Wound, tetanus prophylaxis (≥ 3 doses)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۵۰ ساله با پارگی تمیز کوچک و آخرین دوز کزاز 12 سال پیش.","why":"با 3 دوز یا بیشتر: بسته به زمان آخرین دوز و نوع زخم توکسوئید داده می‌شود؛ TIG لازم نیست."}],"ch":"16","name":"Tetanus prophylaxis for wounds","name_fa":"پیشگیری از کزاز در زخم‌ها","cc":["wound-bite"],"keywords":"tetanus toxoid, TIG, Tdap, tetanus immune globulin, immunization","status":"draft","features":["مکانیسم آسیب، سن زخم و وضعیت واکسیناسیون کزاز را بررسی کن","تنها منع مطلق توکسوئید کزاز: سابقه واکنش عصبی یا شدید سیستمیک بعد از دوز قبلی","«سایر زخم‌ها» شامل: مراقبت تأخیری (> 6 ساعت)، عمیق (> 1 cm)، آلودگی شدید، تماس با بزاق یا مدفوع، ستاره‌ای، ایسکمیک یا عفونی، آواسیون، پانکچر و له‌شدگی"],"ddx":[{"n":"Contaminated / high-risk wound |","cm":1},{"n":"Clean minor wound |"}],"redflags":["واکنش شدید قبلی به توکسوئید"],"guide":"توکسوئید: Tdap در بالغ بدون ثبت قبلی؛ در غیر این صورت Td اگر > 7 سال و DT اگر < 7 سال، ترجیحاً در دلتوئید. ایمونوگلوبولین (TIG) بالغ: 250–500 IU در دلتوئید طرف مقابل محل توکسوئید.","section":"wounds","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 16: Postrepair Wound Care, pp. 121–124"}});
